import { Injectable } from '@nestjs/common';
import { Pool } from 'pg';

/**
 * Persists the link-graph edges produced by the crawler's parsing stage.
 * `link_graph` rows are edges: from_url -> to_url (an outlink discovered on fromUrl's page).
 * PageRank later scans this table and uses each URL's inbound edge count as its in-degree signal.
 */
@Injectable()
export class LinkGraphRepository {
  constructor(private readonly pool: Pool) {}

  /**
   * Called by the crawler every time it (re-)parses a page: saveOutlinks(pageUrl, extractedLinks).
   * A page gets re-parsed on every re-crawl, and its extracted outlinks may shrink, grow,
   * or change entirely between parses.
   */
  async saveOutlinks(fromUrl: string, outlinks: string[]): Promise<void> {
    for (const toUrl of outlinks) {
      await this.pool.query(
        `INSERT INTO link_graph (from_url, to_url)
         VALUES ($1, $2)
         ON CONFLICT (from_url, to_url) DO NOTHING`,
        [fromUrl, toUrl],
      );
    }
  }
}
